package org.ubuntuquest.pocket;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import java.io.*;import java.util.*;import org.json.*;
final class Convergence {
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("convergence",0);}
 static int width(Activity a){View v=a.findViewById(android.R.id.content);if(v instanceof android.view.ViewGroup&&((android.view.ViewGroup)v).getChildCount()>0)v=((android.view.ViewGroup)v).getChildAt(0);return v!=null&&v.getWidth()>0?Math.round((v.getWidth()-v.getPaddingLeft()-v.getPaddingRight())/a.getResources().getDisplayMetrics().density):DeviceProfiles.width(a);}
 static String layoutSetting(Context c){String profile=DeviceProfiles.current(c);return HeadsetLaunchPolicy.layout(profile,prefs(c).getString(HeadsetLaunchPolicy.layoutKey(profile),"auto"));}
 static void setMode(Context c,String mode){prefs(c).edit().putString(HeadsetLaunchPolicy.layoutKey(DeviceProfiles.current(c)),mode).apply();changed(c);}
 static String mode(Activity a){return ConvergencePolicy.mode(width(a),layoutSetting(a));}
 static final java.util.concurrent.ExecutorService io=java.util.concurrent.Executors.newSingleThreadExecutor();
 static void publish(Activity a){if(!(a instanceof MainActivity||a instanceof PhoneHomeActivity||a instanceof MonitorPanelActivity||a instanceof ExternalDesktopActivity))return;Context c=a.getApplicationContext();int width=width(a),height=Math.round(a.getWindow().getDecorView().getHeight()/a.getResources().getDisplayMetrics().density);boolean pointer=DeviceProfiles.pointer(),keyboard=DeviceProfiles.keyboard(),external=a.getWindowManager().getDefaultDisplay().getDisplayId()!=0;io.execute(()->{try{Engine e=Engine.get(c);if(!e.desktopReady)return;JSONObject p=new JSONObject().put("session",e.device.session).put("updated",System.currentTimeMillis()).put("width",width).put("height",height).put("pointer",pointer).put("keyboard",keyboard).put("external",external);LauncherBridge.atomic(new File(e.root,"opt/ubuntuquest/convergence-host.json"),p.toString());settings(c);}catch(Exception ignored){}});}
 static void settings(Context c)throws Exception{Engine e=Engine.get(c);if(!e.desktopReady)return;SharedPreferences p=prefs(c);LauncherBridge.atomic(new File(e.root,"opt/ubuntuquest/convergence-settings.json"),new JSONObject().put("mode",layoutSetting(c)).put("review",p.getBoolean("review",true)).put("split",ConvergencePolicy.split(p.getInt("split",50))).put("automatic",p.getBoolean("automatic",true)).put("remember",p.getBoolean("remember",true)).toString());}
 static void changed(Context c){io.execute(()->{try{settings(c);}catch(Exception ignored){}});}
 static void send(Context c,String action){io.execute(()->{try{Engine e=Engine.get(c);if(!e.desktopReady)throw new IOException("Start Ubuntu first");settings(c);LauncherBridge.atomic(new File(e.root,"opt/ubuntuquest/convergence-command.json"),new JSONObject().put("action",action).put("request",UUID.randomUUID().toString().replace("-","")).put("session",e.device.session).put("created",System.currentTimeMillis()).toString());}catch(Exception error){new Handler(Looper.getMainLooper()).post(()->android.widget.Toast.makeText(c,error.getMessage(),1).show());}});}
 static void release(android.view.View v){if(v instanceof DesktopView)((DesktopView)v).releaseRemoteInput();if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++)release(g.getChildAt(i));}}
 static void controls(Activity a,android.view.View v){if(v instanceof AdaptivePanels)((AdaptivePanels)v).refreshMode();if(v instanceof android.widget.Button){int size=Math.round(VrProfile.target(a,DeviceProfiles.compact(a)?48:56)*a.getResources().getDisplayMetrics().density);((android.widget.Button)v).setMinHeight(size);((android.widget.Button)v).setMinimumHeight(size);}if(v instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)v;for(int i=0;i<group.getChildCount();i++)controls(a,group.getChildAt(i));}}
 static void terminal(Activity a){if(!Engine.get(a).desktopReady){a.startActivity(new Intent(a,MainActivity.class).setAction(MainActivity.OPEN_DESKTOP).putExtra("ubuntu-app",LauncherToken.of("droibuntu-terminal.desktop")));return;}UbuntuLaunch.open(a,LauncherToken.of("droibuntu-terminal.desktop"),null,null,null);}
 private Convergence(){}
}
